arguments.command:
cd ~/.openclaw && python3 - <<'EOF'
import json,glob,os
for f in ["cron/jobs-state.json.migrated","cron/jobs.json.bak","cron/jobs.json.migrated"]:
    p=os.path.expanduser("~/.openclaw/"+f)
    if not os.path.exists(p): continue
    try: d=json.load(open(p))
    except Exception as e: print(f,"ERR",e); continue
    jobs = d.get("jobs", d) if isinstance(d,dict) else d
    print("=== ",f, type(jobs), len(jobs) if hasattr(jobs,'__len__') else '')
    if isinstance(jobs,list):
        for j in jobs:
            print(j.get("id"),"|",j.get("name"),"|",j.get("schedule"),"|",j.get("agentId"),"|enabled=",j.get("enabled"))
EOF

