cd ~/.openclaw && python3 - <<'EOF'
import json
d=json.load(open("openclaw.json"))
def walk(o,p=""):
    if isinstance(o,dict):
        for k,v in o.items():
            if any(s in k.lower() for s in ("embed","memory","provider")):
                print(p+k,"=",json.dumps(v,ensure_ascii=False)[:600])
            else:
                walk(v,p+k+".")
walk(d)
EOF

